(() => {
// Address check before a signup reaches the list (22 Nov 2026). Until then the forms only tested the shape, and
// typos such as gmail.con or gmai.com got in: they bounce or, worse, land on typo domains that accept anything and
// count against the sender's reputation. One pass over the 14,300 signups set 125 aside (KV `invalido:<address>`).
//
// This file is the single source: public/correo.js (what runs in the browser to offer "¿Querías decir…?") is
// generated from it with `node scripts/correo-web.mjs`. The Worker also uses it to refuse on the server.

// Real providers: anything close to one of these without being it is a typo.
const PROVIDERS = ['gmail.com', 'googlemail.com', 'hotmail.com', 'hotmail.es', 'outlook.com', 'outlook.es', 'yahoo.com', 'yahoo.es', 'icloud.com',
  'live.com', 'live.es', 'msn.com', 'me.com', 'mac.com', 'telefonica.net', 'protonmail.com', 'proton.me', 'gmx.es', 'gmx.com',
  'ymail.com', 'aol.com', 'orange.es', 'movistar.es', 'terra.es'];
// Real domains that happen to look like one of PROVIDERS: left alone.
const LOOKALIKES = new Set(['mail.com', 'email.com', 'gmx.net', 'gmx.de', 'usa.com', 'live.it', 'live.fr', 'live.ru', 'live.co.uk',
  'hotmail.fr', 'hotmail.de', 'hotmail.it', 'hotmail.co.uk', 'outlook.fr', 'outlook.it', 'outlook.de', 'yahoo.it', 'yahoo.fr',
  'yahoo.de', 'yahoo.ca', 'yahoo.ie', 'yahoo.co.uk', 'yahoo.com.ar', 'yahoo.com.mx', 'hotmail.com.ar', 'live.com.mx', 'aol.es']);
// Throwaway inboxes.
const DISPOSABLE = new Set(['yopmail.com', 'yopmail.fr', 'yopmail.net', 'mailinator.com', 'guerrillamail.com', 'sharklasers.com',
  '10minutemail.com', 'temp-mail.org', 'tempmail.com', 'trashmail.com', 'maildrop.cc', 'getnada.com', 'dispostable.com',
  'mailnesia.com', 'tempail.com', 'emailondeck.com', 'fakeinbox.com', 'mohmal.com', 'minuteinbox.com', 'zeromail.link']);
// Providers with a single domain: gmail.es or gmail.co is always gmail.com.
const SINGLE = { gmail: 'gmail.com', googlemail: 'gmail.com', icloud: 'icloud.com', protonmail: 'protonmail.com' };

// Endings that are a slip of ".com" on a phone keyboard, whatever comes before them.
const COM_SLIPS = new Set(['con', 'cpm', 'cmo', 'ocm', 'vom', 'xom', 'clm', 'comm', 'coom', 'ccom', 'comn', 'como', 'coma']);

const SHAPE = /^[a-z0-9._%+'-]+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/;

function distance(a, b) {
  const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length];
}

/**
 * { ok: true } when the address is fine; otherwise { ok: false, reason, suggestion? }.
 * reason: 'shape' | 'typo' | 'disposable'. The suggestion is the same address with the domain corrected.
 */
function checkAddress(input) {
  const address = String(input || '').trim().toLowerCase();
  const at = address.lastIndexOf('@'), user = address.slice(0, at), domain = address.slice(at + 1);
  if (address.length > 254 || !SHAPE.test(address) || address.includes('..') || user.startsWith('.') || user.endsWith('.'))
    return { ok: false, reason: 'shape' };
  if (DISPOSABLE.has(domain)) return { ok: false, reason: 'disposable' };
  if (PROVIDERS.includes(domain) || LOOKALIKES.has(domain)) return { ok: true };
  const tld = domain.slice(domain.lastIndexOf('.') + 1);
  if (COM_SLIPS.has(tld)) {
    const fixed = `${domain.slice(0, domain.lastIndexOf('.'))}.com`;
    return { ok: false, reason: 'typo', suggestion: `${user}@${checkAddress(`${user}@${fixed}`).suggestion?.split('@')[1] || fixed}` };
  }
  let fix = domain === 'googlemail.com' ? null : SINGLE[domain.split('.')[0]];
  if (!fix) {
    let best = 3;
    for (const p of PROVIDERS) { const n = distance(domain, p); if (n < best) { best = n; fix = p; } }
  }
  return fix ? { ok: false, reason: 'typo', suggestion: `${user}@${fix}` } : { ok: true };
}

const hintFor = (input) => {
  let p = input.form.querySelector('.correo-aviso');
  if (!p) {
    p = document.createElement('p');
    p.className = 'correo-aviso';
    p.setAttribute('role', 'alert');
    p.style.cssText = 'display:block;width:100%;flex:0 0 100%;grid-column:1/-1;box-sizing:border-box;margin:8px 0 0;font-size:16px;font-weight:600;line-height:1.4;color:inherit';
    // Under the field's own row: where the field shares a row with the button (.linea), under that row.
    (input.parentElement === input.form ? input : input.parentElement).insertAdjacentElement('afterend', p);
  }
  return p;
};
const clear = (input) => { const p = input.form && input.form.querySelector('.correo-aviso'); if (p) p.remove(); };
function warn(input, verdict) {
  const p = hintFor(input);
  p.textContent = '';
  if (verdict.reason === 'typo') {
    p.append('¿Querías decir ');
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = verdict.suggestion;
    b.style.cssText = 'font:inherit;font-weight:800;color:inherit;background:none;border:0;padding:0;text-decoration:underline;cursor:pointer';
    b.addEventListener('click', () => { input.value = verdict.suggestion; clear(input); input.focus(); });
    p.append(b, '? Pulsa para corregirlo.');
  } else {
    p.textContent = 'Ese correo es de usar y tirar. Pon uno que mires de verdad.';
  }
  window.umami && window.umami.track('correo_aviso', { reason: verdict.reason });
}
const field = (el) => el && el.name === 'correo' && el.form ? el : null;
document.addEventListener('change', (e) => {
  const input = field(e.target);
  if (!input) return;
  const v = checkAddress(input.value);
  if (v.ok || v.reason === 'shape') clear(input); else warn(input, v);
}, true);
document.addEventListener('input', (e) => { const input = field(e.target); if (input) clear(input); }, true);
document.addEventListener('submit', (e) => {
  const input = e.target.querySelector && e.target.querySelector('input[name="correo"]');
  if (!input) return;
  const v = checkAddress(input.value);
  if (v.ok || v.reason === 'shape') return;
  e.preventDefault();
  e.stopImmediatePropagation();
  warn(input, v);
  input.focus();
}, true);
})();
